//! The running bot's memory module, `memory.rs` (D-105, C-026).

use proc_macro2::TokenStream;
use quote::quote;

/// `memory.rs`: the values in `data.json`, held in memory and written after each change.
#[allow(clippy::too_many_lines)] // the module's source, as data
pub(crate) fn module() -> TokenStream {
    quote! {
        #![doc = " The bot's memory, kept in `data.json` next to the bot. Generated by RustBot"]
        #![doc = " Creator: do not edit, it is overwritten on every build."]
        // Not every bot uses every function.
        #![allow(dead_code)]

        use std::collections::BTreeMap;
        use std::sync::{Mutex, PoisonError};

        use serde_json::Value;

        /// Values by variable, then by key: empty for the bot, a server's ID, a user's ID,
        /// or both as `server:user`.
        type Store = BTreeMap<String, BTreeMap<String, Value>>;

        const PATH: &str = "data.json";
        const TEMPORARY: &str = "data.json.tmp";

        static STORE: Mutex<Option<Store>> = Mutex::new(None);

        /// Reads `data.json` when the bot starts. A damaged file stops the bot instead of
        /// being overwritten, so no value is lost.
        pub(crate) fn load() -> Result<(), Box<dyn std::error::Error>> {
            let store = match std::fs::read(PATH) {
                Ok(bytes) => serde_json::from_slice(&bytes).map_err(|error| {
                    format!("{PATH} is damaged ({error}); fix it or move it away")
                })?,
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => Store::new(),
                Err(error) => return Err(format!("cannot read {PATH}: {error}").into()),
            };
            *STORE.lock().unwrap_or_else(PoisonError::into_inner) = Some(store);
            Ok(())
        }

        // shortcut: the lock is held while the file is written, and the whole file is
        // written on each change; fine for thousands of values, use a database when bots
        // get bigger.
        fn with<T>(work: impl FnOnce(&mut Store) -> T) -> T {
            let mut store = STORE.lock().unwrap_or_else(PoisonError::into_inner);
            work(store.get_or_insert_with(Store::new))
        }

        /// A value as text, or `start` when nothing set it.
        pub(crate) fn read(name: &str, key: &str, start: &str) -> String {
            with(|store| match store.get(name).and_then(|values| values.get(key)) {
                Some(Value::String(text)) => text.clone(),
                Some(other) => other.to_string(),
                None => start.to_owned(),
            })
        }

        /// A number as it is kept: whole numbers without `.0`.
        pub(crate) fn number(value: f64) -> Value {
            if value.fract() == 0.0 && value.abs() < 9e15 {
                Value::from(value as i64)
            } else {
                Value::from(value)
            }
        }

        pub(crate) fn set(name: &str, key: &str, value: Value) -> std::io::Result<()> {
            with(|store| put(store, name, key, Some(value)))
        }

        /// Adds `amount` to a number, which is `start` when nothing set it.
        pub(crate) fn change(name: &str, key: &str, amount: f64, start: f64) -> std::io::Result<()> {
            with(|store| {
                let current = store
                    .get(name)
                    .and_then(|values| values.get(key))
                    .and_then(Value::as_f64)
                    .unwrap_or(start);
                let sum = current + amount;
                if !sum.is_finite() {
                    return Err(std::io::Error::other("the number got too big"));
                }
                put(store, name, key, Some(number(sum)))
            })
        }

        /// The users with the most of a number (D-122), as lines `1. <@id> — 120`: the
        /// keys that are `prefix` and a user's ID. A dash when nobody has one yet.
        pub(crate) fn ranking(name: &str, prefix: &str, count: usize) -> String {
            let mut values: Vec<(String, f64)> = with(|store| {
                store.get(name).map_or_else(Vec::new, |values| {
                    values
                        .iter()
                        .filter_map(|(key, value)| {
                            Some((key.strip_prefix(prefix)?.to_owned(), value.as_f64()?))
                        })
                        .collect()
                })
            });
            values.sort_by(|a, b| b.1.total_cmp(&a.1));
            let lines: Vec<String> = values
                .iter()
                .take(count)
                .enumerate()
                .map(|(ix, (user, value))| format!("{}. <@{user}> — {}", ix + 1, number(*value)))
                .collect();
            if lines.is_empty() {
                "—".to_owned()
            } else {
                lines.join("\n")
            }
        }

        /// Back to the starting value.
        pub(crate) fn reset(name: &str, key: &str) -> std::io::Result<()> {
            with(|store| put(store, name, key, None))
        }

        /// Changes one value and saves; if saving fails, the old value stays.
        fn put(store: &mut Store, name: &str, key: &str, value: Option<Value>) -> std::io::Result<()> {
            let values = store.entry(name.to_owned()).or_default();
            let old = match value {
                Some(value) => values.insert(key.to_owned(), value),
                None => values.remove(key),
            };
            let saved = save(store);
            if saved.is_err() {
                let values = store.entry(name.to_owned()).or_default();
                match old {
                    Some(old) => values.insert(key.to_owned(), old),
                    None => values.remove(key),
                };
            }
            saved
        }

        /// Writes a new file and renames it over the old one, so a crash leaves one of
        /// them whole.
        fn save(store: &Store) -> std::io::Result<()> {
            let text = serde_json::to_vec_pretty(store)?;
            let mut file = std::fs::File::create(TEMPORARY)?;
            std::io::Write::write_all(&mut file, &text)?;
            file.sync_all()?;
            std::fs::rename(TEMPORARY, PATH)
        }
    }
}
